import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    # ||f*f||_2^2 = sum (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3
    L2 = L * L
    num = (L2[:-1].sum() + (L[:-1] * L[1:]).sum() + L2[1:].sum()) / 3.0
    den1 = h.sum() ** 2
    inf = L.max()
    if den1 <= 0 or inf <= 0:
        return 0.0
    return num / (den1 * inf)


def _gauss(N, s):
    i = np.arange(N, dtype=float)
    x = (i - (N - 1) / 2.0) / s
    return np.exp(-0.5 * x * x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best_h = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size and np.all(np.isfinite(s)) and s.sum() > 0:
            r = _R(s)
            if r > best_R:
                best_R = r
                best_h = s.copy()

    # Coarse search
    Ns = [100, 200, 400, 800, 1600, 3200]
    ratios = np.linspace(0.02, 0.30, 29)
    for N in Ns:
        for ratio in ratios:
            if time.process_time() > deadline:
                break
            s = ratio * N
            h = _gauss(N, s)
            r = _R(h)
            if r > best_R:
                best_R = r
                best_h = h.copy()
        if time.process_time() > deadline:
            break

    # Refinement: shrink around best (N, ratio)
    if best_h is not None:
        # recover approximate ratio from best_h width
        N = best_h.size
        # estimate s from second moment
        i = np.arange(N, dtype=float)
        w = best_h / best_h.sum()
        mean = (w * i).sum()
        var = (w * (i - mean) ** 2).sum()
        s_est = np.sqrt(var)
        ratio_est = s_est / N
    else:
        N = 400
        ratio_est = 0.12

    N_lo, N_hi = max(50, N // 2), min(200000, N * 2)
    r_lo, r_hi = max(0.005, ratio_est * 0.5), min(0.5, ratio_est * 2.0)

    step_N = max(1, (N_hi - N_lo) // 8)
    step_r = (r_hi - r_lo) / 8.0

    while time.process_time() < deadline:
        improved = False
        for N in range(N_lo, N_hi + 1, max(1, step_N)):
            if time.process_time() > deadline:
                break
            for ratio in np.arange(r_lo, r_hi + 1e-12, step_r):
                if time.process_time() > deadline:
                    break
                s = max(1e-6, ratio * N)
                h = _gauss(N, s)
                r = _R(h)
                if r > best_R:
                    best_R = r
                    best_h = h.copy()
                    improved = True
        # shrink
        if step_N <= 1 and step_r < 1e-4:
            # local polish around best
            N = best_h.size
            i = np.arange(N, dtype=float)
            w = best_h / best_h.sum()
            mean = (w * i).sum()
            var = (w * (i - mean) ** 2).sum()
            s_est = np.sqrt(var)
            for dN in [-2, -1, 0, 1, 2]:
                NN = N + dN
                if NN < 1:
                    continue
                for ds in np.linspace(-2, 2, 9):
                    if time.process_time() > deadline:
                        break
                    h = _gauss(NN, max(1e-6, s_est + ds))
                    r = _R(h)
                    if r > best_R:
                        best_R = r
                        best_h = h.copy()
            if time.process_time() > deadline:
                break
            if not improved:
                break
        else:
            N_lo = max(50, N_lo + step_N // 2)
            N_hi = min(200000, N_hi - step_N // 2)
            r_lo = max(0.005, r_lo + step_r / 2)
            r_hi = min(0.5, r_hi - step_r / 2)
            step_N = max(1, step_N // 2)
            step_r = step_r / 2.0
            if N_lo > N_hi:
                N_lo, N_hi = 50, 200000
            if r_lo >= r_hi:
                break

    if best_h is None:
        return np.ones(50)
    return best_h

import numpy as np
import time


def _R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    # ||f*f||_2^2 up to factor 1/3
    q = np.dot(L, L) + np.dot(L[:-1], L[1:])
    m = L.max()
    if m <= 0:
        return -1.0
    return q / (3.0 * s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + 0.9 * budget_seconds

    N = 500
    i = np.arange(N, dtype=float)
    c = (N - 1) / 2.0
    sigma = N / 10.0
    h = np.exp(-0.5 * ((i - c) / sigma) ** 2)

    # If a start exists, try to use it (resample to N) as an alternative seed.
    if start is not None:
        start = np.asarray(start, dtype=float)
        if start.size > 1 and start.size != N:
            xs = np.linspace(0, 1, start.size)
            xn = np.linspace(0, 1, N)
            hs = np.interp(xn, xs, start)
            if _R(hs) > _R(h):
                h = hs
        elif start.size == N:
            if _R(start) > _R(h):
                h = start.copy()

    best = _R(h)
    best_h = h.copy()

    delta = 0.2
    rng = np.random.default_rng(12345)

    while time.process_time() < deadline:
        improved = False
        # coordinate sweep
        order = rng.permutation(N)
        for idx in order:
            if time.process_time() >= deadline:
                break
            old = h[idx]
            if old <= 0:
                # try growing from zero
                h[idx] = 1e-3 * (h.mean() if h.mean() > 0 else 1.0)
                r = _R(h)
                if r > best:
                    best = r
                    best_h = h.copy()
                    improved = True
                else:
                    h[idx] = old
                continue
            for sign in (1.0, -1.0):
                h[idx] = old * (1.0 + sign * delta)
                if h[idx] < 0:
                    h[idx] = 0.0
                r = _R(h)
                if r > best:
                    best = r
                    best_h = h.copy()
                    improved = True
                    break
                else:
                    h[idx] = old
        if not improved:
            if delta > 1e-6:
                delta *= 0.5
            else:
                # random pair perturbations
                for _ in range(50):
                    if time.process_time() >= deadline:
                        break
                    a, b = rng.integers(0, N, size=2)
                    if a == b:
                        continue
                    ha, hb = h[a], h[b]
                    scale = 0.05 * delta if delta > 0 else 0.01
                    h[a] = max(0.0, ha * (1 + rng.normal(0, scale)))
                    h[b] = max(0.0, hb * (1 + rng.normal(0, scale)))
                    r = _R(h)
                    if r > best:
                        best = r
                        best_h = h.copy()
                        improved = True
                    else:
                        h[a], h[b] = ha, hb
                if not improved:
                    delta *= 0.5
                    if delta < 1e-8:
                        break

    print("final R =", best)
    return best_h
